records=[
 dict(id='PAPER-E001',title='A strengthening of the Nyman-Beurling criterion for the Riemann hypothesis, 2',authors=['Luis Báez-Duarte'],date='2002-05-01',year=2002,doi=None,arxiv='math/0205003',source_url='https://arxiv.org/abs/math/0205003v1',version='v1',family=['C','A'],audit_level=1,read_scope='Complete nine-page preprint text read; ordered-limit argument reconstructed; external dependencies not fully independently checked.',access_status='full_text_accessed',venue='arXiv preprint; distinct from original math/0202141 and subsequent published text',publication_status='preprint_version_inspected',source_file='baez_duarte',main_result='In H=L²((0,infinity),dx), let rho_a(x)={1/(a x)}, chi=1_(0,1], and B_nat=span{rho_a:a in positive integers}. RH iff chi belongs to the H closure of B_nat (Theorem1.1, pp.1–2). Under RH, for some c>0, ||chi+sum_{a<=n}mu(a)exp(-c log(a)/loglog(n))rho_a||_H << (loglog(n))^(-1/3) (Proposition3.1, pp.6–8).',proof_architecture=['RH plus Balazard–Saias truncated Möbius estimate','Mellin transform of fractional part is -zeta(s)/s in 0<Re(s)<1','Functional-equation ratio bound Lemma2.2','H convergence n→infinity for fixed sufficiently small epsilon','H convergence epsilon↓0 to -chi, then closure'],limitations=['No RH-independent construction attaining convergence is supplied.','The two limits are ordered; pointwise convergence of raw Möbius truncations does not imply H convergence.','Proposition3.1 is a sketch with external input.','Displayed integrability range in p.5 needs epsilon<1/4 for the particular majorant; sufficiently small epsilon suffices.'],historical_importance='Reduces continuous dilation parameters to integer dilations; turns an abstract closure criterion into arithmetic approximation.',reusable_lemma='Lemma2.2 bounds |zeta(1/2-epsilon+it)/zeta(1/2+epsilon+it)| by C(1+|t|)^epsilon, for 0<=epsilon<=epsilon0<1/2, interpreted at removable common zeros; the functional equation supplies the modulus bound.',research_questions=['Can a quantitative uniform error bound replace the sequential limiting argument?','Which smoothing schemes preserve norm convergence with a useful explicit rate?']),
 dict(id='PAPER-E002',title='A lower bound in an approximation problem involving the zeros of the Riemann zeta function',authors=['Jean-François Burnol'],date='2001-03-20',year=2001,doi='10.1006/aima.2001.2066',arxiv='math/0103058',source_url='https://arxiv.org/abs/math/0103058v2',version='v2',family=['C','D','F'],audit_level=1,read_scope='Complete 17 printed-page preprint read; polynomial jet-projection method reconstructed; zeta invariant-operator lemmas read but not independently rebuilt.',access_status='full_text_accessed',venue='Advances in Mathematics 170 (2002), 56–70; inspected 2001 preprint',publication_status='published_work_preprint_inspected',source_file='burnol',main_result='For B_lambda=span{{theta/t}:lambda<=theta<=1} in L²((0,infinity),dt), D(lambda)=dist(chi,B_lambda), liminf_{lambda↓0}D(lambda)*sqrt(log(1/lambda)) >= sqrt(sum_rho m_rho²/|rho|²) (Theorem1.3 p.4; Theorem5.5 pp.15–16). Proof assumes RH, since its failure makes the left side infinite; rho are distinct nontrivial zeros under that assumption. Polynomial analogue Theorem1.4: Q of positive degree with all roots alpha on the unit circle, multiplicities m_alpha, and fixed target polynomial P gives lim N inf_deg A<=N ||P-QA||²=sum_alpha m_alpha²|P(alpha)|².',proof_architecture=['Finite-dimensional prediction error and jet evaluation Gram matrices (§2)','Mellin invariant unitary phase operator V (§3)','Boundary-limit Hilbert vectors Y_(s,k)^lambda and orthogonality to contracted zeta model (§4)','Rescale by log(1/lambda)^(-k-1/2)','Fixed finite set of zeros gives Cauchy Gram blocks, whose inverse top-left entries are m²','Take lower bound for every finite zero set; then increase the finite set'],limitations=['A lower bound only; no upper bound or complete spectral construction follows.','Fixed finite-set Gram limits do not justify a uniform infinite-set limit.','The conjectural disappearance of the continuous quotient component is explicitly speculative.','D(lambda) allows continuous dilation parameters; discrete Dirichlet-polynomial distance is at least as large at lambda=1/N.'],historical_importance='Identifies multiplicity squared, not multiplicity, as the approximation obstruction; converts zero jets to asymptotic Gram blocks.',reusable_lemma='Theorem5.3: distinct fixed zeros have asymptotically vanishing cross Gram entries after scaling; same-zero derivative jets give 1/(k+l+1).',research_questions=['Obtain uniform Gram estimates when zero separations shrink with the cutoff.','Control any orthogonal complement beyond the constructed zero jets before asserting a matching upper bound.']),
 dict(id='PAPER-E003',title='An optimal choice of Dirichlet polynomials for the Nyman-Beurling criterion',authors=['Sandro Bettin','J. Brian Conrey','David W. Farmer'],date='2012-11-22',year=2012,doi='10.1134/S0081543813030036',arxiv='1211.5191',source_url='https://arxiv.org/abs/1211.5191v1',version='v1',family=['A','C'],audit_level=1,read_scope='Complete nine-page preprint read; hypotheses and residue proof architecture extracted; central contour estimates inspected, not all independently verified.',access_status='full_text_accessed',venue='Proceedings of the Steklov Institute of Mathematics, 2013; preprint version inspected',publication_status='published_work_preprint_inspected',source_file='bcf',main_result='Assume RH and sum_{|Im rho|<=T}|zeta\'(rho)|^(-2)<<T^(3/2-delta) for some delta>0. For V_N(s)=sum_{n<=N}(1-log n/log N)mu(n)n^(-s), N>1, its squared weighted critical-line error (1/(2pi))integral_R |1-zeta(1/2+it)V_N(1/2+it)|² dt/(1/4+t²) is asymptotic to (2+gamma-log(4pi))/log N (Theorem1,p.2). Moment hypothesis forces simple zeros. Theorem2,p.3: analogous triangular reciprocal Taylor window is asymptotically optimal for polynomials with simple roots on/outside the circle, if boundary roots are present.',proof_architecture=['Perron representation of logarithmically weighted Möbius polynomial','Residues at pole s, nontrivial zeros, and trivial zeros (Lemma2)','Reciprocal derivative moment controls sums of zero residues (Lemma3)','Shift norm contour off critical line','Double pole residue supplies sum 1/|rho|² log N; remaining integrals are lower order'],limitations=['RH alone is not the theorem hypothesis.','Inverse derivative moment excludes multiplicities.','Infinite-zero residue tails require the additional moment estimate.','No finite-N inequality of the form d_N²>=C/log N is proved.','Polynomial theorem with no boundary roots should be read as o(1/N), rather than literal asymptotic equivalence to zero.'],historical_importance='Under an explicit strong arithmetic hypothesis, a concrete logarithmic Möbius smoothing attains Burnol’s asymptotic lower constant.',reusable_lemma='Lemma3 pp.6–7 supplies a bound on the sum of zero-residue terms on Re(s)=1/2±epsilon using the negative derivative moment.',research_questions=['Can collective residue cancellation weaken the exponent 3/2-delta?','Which estimates replace inverse simple derivatives for higher principal parts?'])]
